6	import { randomUUID } from 'node:crypto';
7	import type { JSONSchemaType } from 'ajv';
8	import type {
9	  ContextProcessor,
10	  ProcessArgs,
11	  BackstopTargetOptions,
12	} from '../pipeline.js';
13	import type { ContextEnvironment } from '../pipeline/environment.js';
14	import { type ConcreteNode, type Snapshot, NodeType } from '../graph/types.js';
15	import { SnapshotGenerator } from '../utils/snapshotGenerator.js';
16	import { debugLogger } from '../../utils/debugLogger.js';
17	
18	export interface StateSnapshotProcessorOptions extends BackstopTargetOptions {
19	  model?: string;
20	  systemInstruction?: string;
21	}
22	
23	export const StateSnapshotProcessorOptionsSchema: JSONSchemaType<StateSnapshotProcessorOptions> =
24	  {
25	    type: 'object',
26	    properties: {
27	      target: {
28	        type: 'string',
29	        enum: ['incremental', 'freeNTokens', 'max'],
30	        nullable: true,
31	      },
32	      freeTokensTarget: { type: 'number', nullable: true },
33	      model: { type: 'string', nullable: true },
34	      systemInstruction: { type: 'string', nullable: true },
35	    },
36	    required: [],
37	  };
38	
39	export function createStateSnapshotProcessor(
40	  id: string,
41	  env: ContextEnvironment,
42	  options: StateSnapshotProcessorOptions,
43	): ContextProcessor {
44	  const generator = new SnapshotGenerator(env);
45	
46	  return {
47	    id,
48	    name: 'StateSnapshotProcessor',
49	    process: async ({ targets, inbox }: ProcessArgs) => {
50	      if (targets.length === 0) {
51	        return targets;
52	      }
53	
54	      // Determine what mode we are looking for: 'incremental' -> 'point-in-time', 'max' -> 'accumulate'
55	      const strategy = options.target ?? 'max';
56	      const expectedType =
57	        strategy === 'incremental' ? 'point-in-time' : 'accumulate';
58	
59	      // 1. Check Inbox for a completed Snapshot (The Fast Path)
60	      const proposedSnapshots = inbox.getMessages<{
61	        newText: string;
62	        consumedIds: string[];
63	        type: string;
64	        timestamp: number;
65	      }>('PROPOSED_SNAPSHOT');
66	
67	      if (proposedSnapshots.length > 0) {
68	        // Filter for the snapshot type that matches our processor mode
69	        const matchingSnapshots = proposedSnapshots.filter(
70	          (s) => s.payload.type === expectedType,
71	        );
72	
73	        // Sort by newest timestamp first (we want the most accumulated snapshot)
74	        const sorted = [...matchingSnapshots].sort(
75	          (a, b) => b.timestamp - a.timestamp,
76	        );
77	
78	        for (const proposed of sorted) {
79	          const { consumedIds, newText, timestamp } = proposed.payload;
80	
81	          // Verify all consumed IDs still exist sequentially in targets
82	          const targetIds = new Set(targets.map((t) => t.id));
83	          const isValid = consumedIds.every((id) => targetIds.has(id));
84	
85	          if (isValid) {
86	            // If valid, apply it!
87	            const newId = randomUUID();
88	
89	            const snapshotNode: Snapshot = {
90	              id: newId,
91	              turnId: newId,
92	              type: NodeType.SNAPSHOT,
93	              timestamp: timestamp ?? Date.now(),
94	              role: 'user',
95	              payload: { text: newText },
96	              abstractsIds: consumedIds,
97	            };
98	
99	            // Remove the consumed nodes and insert the snapshot at the earliest index
100	            const returnedNodes = targets.filter(
101	              (t) => !consumedIds.includes(t.id),
102	            );
103	            const firstRemovedIdx = targets.findIndex((t) =>
104	              consumedIds.includes(t.id),
105	            );
106	
107	            if (firstRemovedIdx !== -1) {
108	              const idx = Math.max(0, firstRemovedIdx);
109	              returnedNodes.splice(idx, 0, snapshotNode);
110	            } else {
111	              returnedNodes.unshift(snapshotNode);
112	            }
113	
114	            inbox.consume(proposed.id);
115	            return returnedNodes;
116	          }
117	        }
118	      }
119	
120	      // 2. The Synchronous Backstop (The Slow Path)
121	      let targetTokensToRemove = 0;
122	
123	      if (strategy === 'incremental') {
124	        targetTokensToRemove = Infinity; // incremental implies removing as much as possible if no state is passed
125	      } else if (strategy === 'freeNTokens') {
126	        targetTokensToRemove = options.freeTokensTarget ?? Infinity;
127	      } else if (strategy === 'max') {
128	        targetTokensToRemove = Infinity;
129	      }
130	
131	      let deficitAccumulator = 0;
132	      const nodesToSummarize: ConcreteNode[] = [];
133	
134	      // Scan oldest to newest
135	      for (const node of targets) {
136	        nodesToSummarize.push(node);
137	        deficitAccumulator += env.tokenCalculator.getTokenCost(node);
138	
139	        if (deficitAccumulator >= targetTokensToRemove) break;
140	      }
141	
142	      if (nodesToSummarize.length < 2) return targets; // Not enough context
143	
144	      try {
145	        const snapshotText = await generator.synthesizeSnapshot(
146	          nodesToSummarize,
147	          options.systemInstruction,
148	        );
149	        const newId = randomUUID();
150	        const snapshotNode: Snapshot = {
151	          id: newId,
152	          turnId: newId,
153	          type: NodeType.SNAPSHOT,
154	          timestamp: nodesToSummarize[nodesToSummarize.length - 1].timestamp,
155	          role: 'user',
156	          payload: { text: snapshotText },
157	          abstractsIds: nodesToSummarize.map((n) => n.id),
158	        };
159	
160	        const consumedIds = nodesToSummarize.map((n) => n.id);
161	        const returnedNodes = targets.filter(
162	          (t) => !consumedIds.includes(t.id),
163	        );
164	        const firstRemovedIdx = targets.findIndex((t) =>
165	          consumedIds.includes(t.id),
166	        );
167	
168	        if (firstRemovedIdx !== -1) {
169	          const idx = Math.max(0, firstRemovedIdx);
170	          returnedNodes.splice(idx, 0, snapshotNode);
171	        } else {
172	          returnedNodes.unshift(snapshotNode);
173	        }
174	
175	        return returnedNodes;
176	      } catch (e) {
177	        debugLogger.error('StateSnapshotProcessor failed sync backstop', e);
178	        return targets;
179	      }
180	    },
181	  };
182	}
