126	    private readonly authType?: AuthType,
127	  ) {}
128	
129	  async generateJson(
130	    options: GenerateJsonOptions,
131	  ): Promise<Record<string, unknown>> {
132	    const {
133	      schema,
134	      modelConfigKey,
135	      contents,
136	      systemInstruction,
137	      abortSignal,
138	      promptId,
139	      role,
140	      maxAttempts,
141	    } = options;
142	
143	    const { model } =
144	      this.config.modelConfigService.getResolvedConfig(modelConfigKey);
145	
146	    const shouldRetryOnContent = (response: GenerateContentResponse) => {
147	      const text = getResponseText(response)?.trim();
148	      if (!text) {
149	        return true; // Retry on empty response
150	      }
151	      try {
152	        // We don't use the result, just check if it's valid JSON
153	        JSON.parse(this.cleanJsonResponse(text, model));
154	        return false; // It's valid, don't retry
155	      } catch {
156	        return true; // It's not valid, retry
157	      }
158	    };
159	
160	    const result = await this._generateWithRetry(
161	      {
162	        modelConfigKey,
163	        contents,
164	        abortSignal,
165	        promptId,
166	        maxAttempts,
167	        systemInstruction,
168	        additionalProperties: {
169	          responseJsonSchema: schema,
170	          responseMimeType: 'application/json',
171	        },
172	      },
173	      shouldRetryOnContent,
174	      'generateJson',
175	      role,
176	    );
177	
178	    // If we are here, the content is valid (not empty and parsable).
179	    // eslint-disable-next-line @typescript-eslint/no-unsafe-return
180	    return JSON.parse(
181	      this.cleanJsonResponse(getResponseText(result)!.trim(), model),
182	    );
183	  }
184	
185	  async generateEmbedding(texts: string[]): Promise<number[][]> {
186	    if (!texts || texts.length === 0) {
187	      return [];
188	    }
189	    const embedModelParams: EmbedContentParameters = {
190	      model: this.config.getEmbeddingModel(),
191	      contents: texts,
192	    };
193	
194	    const embedContentResponse =
195	      await this.contentGenerator.embedContent(embedModelParams);
196	    if (
197	      !embedContentResponse.embeddings ||
198	      embedContentResponse.embeddings.length === 0
199	    ) {
200	      throw new Error('No embeddings found in API response.');
201	    }
202	
203	    if (embedContentResponse.embeddings.length !== texts.length) {
204	      throw new Error(
205	        `API returned a mismatched number of embeddings. Expected ${texts.length}, got ${embedContentResponse.embeddings.length}.`,
206	      );
207	    }
208	
209	    return embedContentResponse.embeddings.map((embedding, index) => {
210	      const values = embedding.values;
211	      if (!values || values.length === 0) {
212	        throw new Error(
213	          `API returned an empty embedding for input text at index ${index}: "${texts[index]}"`,
214	        );
215	      }
216	      return values;
217	    });
218	  }
219	
220	  private cleanJsonResponse(text: string, model: string): string {
221	    const prefix = '```json';
222	    const suffix = '```';
223	    if (text.startsWith(prefix) && text.endsWith(suffix)) {
224	      logMalformedJsonResponse(
225	        this.config,
226	        new MalformedJsonResponseEvent(model),
227	      );
228	      return text.substring(prefix.length, text.length - suffix.length).trim();
229	    }
230	    return text;
231	  }
