233	  async countTokens(
234	    options: CountTokenOptions,
235	  ): Promise<{ totalTokens: number }> {
236	    const model = options.modelConfigKey
237	      ? this.config.modelConfigService.getResolvedConfig(options.modelConfigKey)
238	          .model
239	      : this.config.getActiveModel();
240	    const result = await this.contentGenerator.countTokens({
241	      model,
242	      contents: options.contents,
243	    });
244	    return { totalTokens: result.totalTokens || 0 };
245	  }
