247	  async generateContent(
248	    options: GenerateContentOptions,
249	  ): Promise<GenerateContentResponse> {
250	    const {
251	      modelConfigKey,
252	      contents,
253	      systemInstruction,
254	      abortSignal,
255	      promptId,
256	      role,
257	      maxAttempts,
258	    } = options;
259	
260	    const shouldRetryOnContent = (response: GenerateContentResponse) => {
261	      const text = getResponseText(response)?.trim();
262	      return !text; // Retry on empty response
263	    };
264	
265	    return this._generateWithRetry(
266	      {
267	        modelConfigKey,
268	        contents,
269	        systemInstruction,
270	        abortSignal,
271	        promptId,
272	        maxAttempts,
273	      },
274	      shouldRetryOnContent,
275	      'generateContent',
276	      role,
277	    );
278	  }
