import type { ConcreteNode } from '../graph/types.js';

/**
 * Options controlling how nodes are rendered into a transcript.
 */
export interface FormatNodesForLlmOptions {
  /**
   * The maximum number of characters a single tool response may occupy in the
   * rendered transcript before it is truncated in the middle. Defaults to 2000.
   */
  maxToolResponseChars?: number;
}

const DEFAULT_MAX_TOOL_RESPONSE_CHARS = 2000;

/**
 * Truncates a string that exceeds `max` characters by keeping a prefix and a
 * suffix and collapsing the middle into a marker describing how many characters
 * were removed.
 */
function truncateMiddle(text: string, max: number): string {
  if (text.length <= max) {
    return text;
  }
  const removed = text.length - max;
  const prefixLen = Math.floor(max / 2);
  const suffixLen = max - prefixLen;
  const prefix = text.slice(0, prefixLen);
  const suffix = text.slice(text.length - suffixLen);
  return `${prefix}... [TRUNCATED ${removed} chars] ...${suffix}`;
}

/**
 * Renders an ordered list of context nodes into a compact, human-readable
 * transcript suitable for feeding to an LLM.
 *
 * Each node is rendered on its own line using the format:
 *   `[Turn N] [ROLE] [TYPE]: content`
 *
 * - Text payloads render their raw text.
 * - Function calls render as `CALL: name({args})`.
 * - Function responses render as `[SEMANTIC_WRAPPER (toolName)]: {json_response}`,
 *   truncated in the middle when they exceed `maxToolResponseChars`.
 * - Nodes with an undefined role default to `SYSTEM`.
 */
export function formatNodesForLlm(
  nodes: readonly ConcreteNode[],
  options: FormatNodesForLlmOptions = {},
): string {
  const maxToolResponseChars =
    options.maxToolResponseChars ?? DEFAULT_MAX_TOOL_RESPONSE_CHARS;

  let transcript = '';
  let turn = 0;

  for (const node of nodes) {
    turn += 1;

    const role = (node.role ?? 'SYSTEM').toString().toUpperCase();
    const payload = node.payload;

    let content = '';
    if (payload.text) {
      content = payload.text;
    } else if (payload.functionCall) {
      const name = payload.functionCall.name ?? 'unknown_tool';
      content = `CALL: ${name}(${JSON.stringify(payload.functionCall.args ?? {})})`;
    } else if (payload.functionResponse) {
      const toolName = payload.functionResponse.name ?? 'unknown_tool';
      const json = truncateMiddle(
        JSON.stringify(payload.functionResponse.response ?? {}),
        maxToolResponseChars,
      );
      content = `[SEMANTIC_WRAPPER (${toolName})]: ${json}`;
    }

    transcript += `[Turn ${turn}] [${role}] [${node.type}]: ${content}\n`;
  }

  return transcript;
