 */
export interface BaselineSnapshotInfo {
  /** The snapshot node that provides the baseline state. */
  node: ConcreteNode;
  /** The serialized state text carried by the snapshot node. */
  text: string;
}

const DEFAULT_MAX_SUMMARY_TURNS = 5;
const DEFAULT_MAX_STATE_TOKENS = 4000;

/**
