12	/**
13	 * A structured, machine-readable snapshot of the conversation state.
14	 *
15	 * Instead of a free-form prose summary, the memory is decomposed into distinct
16	 * lists so it can be incrementally patched (append / delete) over time:
17	 * - `active_tasks`: what the user/agent is currently working on.
18	 * - `discovered_facts`: durable facts learned about the codebase/domain.
19	 * - `constraints_and_preferences`: user constraints and stated preferences.
20	 * - `recent_arc`: a rolling summary of the most recent turns.
21	 */
22	export interface SnapshotState {
23	  active_tasks: string[];
24	  discovered_facts: string[];
25	  constraints_and_preferences: string[];
26	  recent_arc: string[];
27	}
28	
29	/**
30	 * A patch describing additions/removals to apply to a single list.
31	 */
32	interface ListPatch {
33	  add?: string[];
34	  remove?: string[];
35	}
36	
37	/**
38	 * Information about a baseline snapshot found within a set of nodes.
39	 */
40	export interface BaselineSnapshotInfo {
