99	/**
100	 * Reads a property from an unknown value, returning undefined when the value is
101	 * not a plain object. Confines the single narrowing assertion needed here.
102	 */
103	function getField(value: unknown, key: string): unknown {
104	  if (!value || typeof value !== 'object') return undefined;
105	  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
106	  return (value as Record<string, unknown>)[key];
