113	function coerceState(value: unknown): SnapshotState {
114	  const state = createEmptyState();
115	  if (!value || typeof value !== 'object') return state;
116	  state.active_tasks = asStringArray(getField(value, 'active_tasks'));
117	  state.discovered_facts = asStringArray(getField(value, 'discovered_facts'));
118	  state.constraints_and_preferences = asStringArray(
119	    getField(value, 'constraints_and_preferences'),
120	  );
121	  state.recent_arc = asStringArray(getField(value, 'recent_arc'));
122	  return state;
