125	/**
126	 * Normalizes a per-list patch value into explicit add/remove arrays.
127	 *
128	 * Tolerates two shapes the model may emit:
129	 * - `["item", ...]`            -> items to append.
130	 * - `{ add: [...], remove: [...] }` -> explicit add/remove.
131	 */
132	function normalizeListPatch(value: unknown): ListPatch {
133	  if (Array.isArray(value)) {
134	    return { add: asStringArray(value), remove: [] };
135	  }
136	  if (value && typeof value === 'object') {
137	    return {
138	      add: asStringArray(getField(value, 'add')),
139	      remove: asStringArray(getField(value, 'remove')),
140	    };
141	  }
142	  return { add: [], remove: [] };
143	}
