145	/**
146	 * Applies a list patch: removes deleted items, then appends new items,
147	 * skipping duplicates already present.
148	 */
149	function applyListPatch(
150	  existing: string[],
151	  patch: ListPatch,
152	  globalRemovals: Set<string>,
153	): string[] {
154	  let result = [...existing];
155	
156	  const removals = new Set<string>(globalRemovals);
157	  for (const item of patch.remove ?? []) removals.add(item);
158	  if (removals.size > 0) {
159	    result = result.filter((item) => !removals.has(item));
