180	    if (node.type !== NodeType.SNAPSHOT) continue;
181	    const text = node.payload?.text;
182	    if (typeof text === 'string' && text.trim().length > 0) {
183	      return { node, text };
184	    }
185	  }
186	  return undefined;
187	}
